## Familles monoparentales {#sec-mono}


::: {.cell}

```{.r .cell-code}
df_mono <- data_all |>
  filter(annee == annee_ref) |>
  filter(typmen == "Famille monoparentale")

indic_mono <- indicateurs_pauvrete(df_mono,
  seuils      = seuils_trajectoire,
  mediane_pop = mediane_nationale)

# Statistiques clés
i_mono_60   <- indic_mono |> filter(seuil_pct == 60)
taux_mono_60  <- i_mono_60$taux
eff_mono_60   <- i_mono_60$effectif
cout_mono_60  <- i_mono_60$cout_mds
int_mono_60   <- i_mono_60$intensite

indic_mono |>
  rename(
    `Seuil (%)`                  = seuil_pct,
    `Seuil mensuel (€/UC)`       = seuil_eur,
    `Taux (%)`                   = taux,
    `Effectif (M)`               = effectif,
    `Intensité (%)`              = intensite,
    `Coût d'éradication (Mds €)` = cout_mds
  ) |>
  gt_cnle(
    title = "Coût d'éradication – familles monoparentales"
  ) |>
  tab_style(
    style = list(cell_fill(color = "#2c7bb6"), cell_text(color = "white", weight = "bold")),
    locations = cells_body(rows = `Seuil (%)` == 60)
  )
